#pragma once

// The player input-control policy object held by CClientExoAppInternal; ChangeControlType installs
// one of the two concrete subclasses, CSWPlayerControlDriving or CSWPlayerControlCamRelative. The
// vtable has no virtual destructor.
// idiom-exempt: canonical
class CAurCamera;
class CSWCCreature;

class CSWPlayerControl {
public:
    CSWPlayerControl();
    CSWPlayerControl(unsigned long long id, CAurCamera* pAurCamera);

    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 12 slots
    virtual void UpDown(float f);
    virtual float GetUpDown();
    virtual void LeftRight(float f);
    virtual float GetLeftRight();
    virtual void SetPlayerWalking(int b);
    virtual int GetPlayerWalking();
    virtual void RunKey();
    virtual float GetCurSpeed();
    virtual void MouseLeftRight(float f);
    virtual void MouseUpDown(float f);
    // Returns an int rather than void: the base body returns 0 and both derived overrides return a
    // literal value.
    virtual int Control(float f);
    virtual void ResetDriveAcceleration();
    // </VTABLE-GEN>

    void Initialize();
    void SetCamera(CAurCamera* pAurCamera);
    void SetEnabled(int bEnabled);
    void SetPlayer(unsigned long long id);
    // The controlled creature; defined inline in swplayercontrol.cpp, its only user.
    CSWCCreature* GetPlayer();

    unsigned long long m_objectId;
    CAurCamera* m_pCamera;
    int         m_bEnabled;
};

// The drive-model control reads the pad and mouse axes and integrates them into a velocity. Its
// translation unit also defines the drive integrator, so this class's constructor and Drive are out
// of line.
#ifndef CSWPLAYERCONTROLDRIVING_H
#define CSWPLAYERCONTROLDRIVING_H

class CSWPlayerControlDriving : public CSWPlayerControl {
public:

    CSWPlayerControlDriving(unsigned long long id, CAurCamera* pAurCamera);
    CSWPlayerControlDriving();

    // Re-seeds the whole drive-tuning field run.
    void Init();

    // The per-frame drive integration that Control calls. Not virtual.
    void Drive(float f);

    virtual void UpDown(float f);
    virtual void LeftRight(float f);
    virtual void MouseLeftRight(float f);
    virtual int Control(float f);

    float     m_fAcceleration;
    float     m_fMaxSpeed;
    float     m_fDeceleration;
    union {
        unsigned long long m_nSpeedPair;
        struct
        {
            float m_fForwardSpeed;
            float m_fStrafeSpeed;
        } m_axis;
    };
    union {
        unsigned long long m_nPrevSpeedPair;
        struct
        {
            float m_fPrevForwardSpeed;
            float m_fPrevStrafeSpeed;
        } m_prev;
    };
    unsigned long long m_nReserved1;
    // The per-axis move request the two input hooks accumulate: UpDown sets MOVE_FORWARD for a
    // negative value and MOVE_BACK for a positive one, LeftRight MOVE_STRAFE_LEFT for a negative
    // value and MOVE_STRAFE_RIGHT for a positive one. Control and Drive consume it.
    enum {
        MOVE_FORWARD      = 0x01,
        MOVE_BACK         = 0x02,
        MOVE_STRAFE_LEFT  = 0x10,
        MOVE_STRAFE_RIGHT = 0x20,
    };
    int       m_nMoveMask;
};

#endif

// The camera-relative control, whose movement axes follow the camera rather than the object. It
// overrides the movement and walking accessors and leaves the rest to the base.

#include "SWAccelerationControlers.h"

class CSWPlayerControlCamRelative : public CSWPlayerControl {
public:
    CSWPlayerControlCamRelative(unsigned long long id, CAurCamera* pAurCamera);
    CSWPlayerControlCamRelative();

    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 12 slots
    virtual void UpDown(float f);
    virtual float GetUpDown();
    virtual void LeftRight(float f);
    virtual float GetLeftRight();
    virtual void SetPlayerWalking(int b);
    virtual int GetPlayerWalking();
    virtual float GetCurSpeed();
    virtual int Control(float f);   // returns 1 where the base returns 0
    virtual void ResetDriveAcceleration();
    // </VTABLE-GEN>

    // Feeds a turn velocity to the drive acceleration integrator; not a vtable slot.
    void SetTurnVelocity(float f);

    float GetMaxSpeed();
    void  SetMaxSpeed(float f);
    float GetAcceleration();
    void  SetAcceleration(float f);

    // The constructors tail-call this, so the declaration must be visible to them.
    void Init();

    float     m_upDown;
    float     m_leftRight;
    int       m_bPlayerWalking;
    Vector    m_vTurn;
    int       m_nReserved1;
    int       m_nReserved2;
    int       m_nReserved3;
    float     m_fTurnRate;
    float     m_fMinTurnRate;
    float     m_fMaxTurnRate;
    float     m_fTurnDirection;
    // The drive state the integrator reads, made of this frame's velocity and position, the
    // persistent copies, and the input axis being chased.
    Vector    m_vDriveA;
    Vector    m_vDriveB;
    Vector    m_vDriveVel;
    Vector    m_vDrivePos;
    Vector    m_vDriveTarget;
    char      _pad8c[0x90 - 0x8c];

    Vector& DriveA()      { return m_vDriveA; }
    Vector& DriveB()      { return m_vDriveB; }
    Vector& DriveVel()    { return m_vDriveVel; }
    Vector& DrivePos()    { return m_vDrivePos; }
    Vector& DriveTarget() { return m_vDriveTarget; }
    Vector& TurnVector()  { return m_vTurn; }
    // The drive acceleration integrator, held by value.
    CSWRK4SplitAcceleration m_acceleration;
};
